-- Emotional Remedy Engine: themes → remedies mapping
CREATE TABLE public.homeo_emotional_themes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  emotional_theme TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  short_description TEXT NOT NULL DEFAULT '',
  trigger_patterns TEXT[] NOT NULL DEFAULT '{}',
  dominant_reaction TEXT[] NOT NULL DEFAULT '{}',
  body_correlations TEXT[] NOT NULL DEFAULT '{}',
  likely_remedies_ranked JSONB NOT NULL DEFAULT '[]'::jsonb,
  differential_remedies TEXT[] NOT NULL DEFAULT '{}',
  followup_questions TEXT[] NOT NULL DEFAULT '{}',
  caution_notes TEXT NOT NULL DEFAULT '',
  doctor_notes TEXT NOT NULL DEFAULT '',
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_homeo_emotional_themes_sort ON public.homeo_emotional_themes(sort_order);
CREATE INDEX idx_homeo_emotional_themes_active ON public.homeo_emotional_themes(is_active);
CREATE INDEX idx_homeo_emotional_themes_theme_trgm ON public.homeo_emotional_themes USING gin (emotional_theme gin_trgm_ops);

ALTER TABLE public.homeo_emotional_themes ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Authenticated can view active emotional themes"
  ON public.homeo_emotional_themes FOR SELECT
  TO authenticated
  USING (is_active = true OR public.is_admin_or_super(auth.uid()));

CREATE POLICY "Admins manage emotional themes - insert"
  ON public.homeo_emotional_themes FOR INSERT
  TO authenticated
  WITH CHECK (public.is_admin_or_super(auth.uid()));

CREATE POLICY "Admins manage emotional themes - update"
  ON public.homeo_emotional_themes FOR UPDATE
  TO authenticated
  USING (public.is_admin_or_super(auth.uid()))
  WITH CHECK (public.is_admin_or_super(auth.uid()));

CREATE POLICY "Admins manage emotional themes - delete"
  ON public.homeo_emotional_themes FOR DELETE
  TO authenticated
  USING (public.is_admin_or_super(auth.uid()));

CREATE TRIGGER update_homeo_emotional_themes_updated_at
  BEFORE UPDATE ON public.homeo_emotional_themes
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

-- Seed: 50 themes
